// The factory's local web server: the web interface's files, the state it
// shows (once, and as a stream of changes), and its buttons. It answers only
// requests addressed to this computer by name, and buttons only from its own
// page (which sends PAGE_HEADER), so another web page cannot press them.
import { existsSync, readFileSync, statSync } from "node:fs";
import { createServer, } from "node:http";
import { extname, join, normalize, sep } from "node:path";
import { PICTURE_TYPES } from "./coach/pictures.js";
import { sendTheme, THEME_ROUTES } from "./theme.js";
import { addOnRoutes } from "./add-ons/add-on.js";
import { answerTools } from "./coach/setup-tools.js";
import { Refused } from "./refused.js";
export const PAGE_HEADER = "x-software-factory";
// The coaches' tools, which check the coach's own token instead: the setup
// coach's, and each idea's.
const COACH_TOOLS = "/api/setup/mcp";
const IDEA_TOOLS = /^\/api\/ideas\/mcp\/([\w-]+)$/;
// A picture from the project that a setup card shows.
const PICTURE = "/api/setup/picture";
const HOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);
const TYPES = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".ico": "image/x-icon",
    ".json": "application/json",
    ".woff2": "font/woff2",
};
export function startServer(options) {
    const watchers = new Set();
    const changed = () => {
        const data = `data: ${JSON.stringify(options.session.state())}\n\n`;
        for (const response of watchers)
            response.write(data);
    };
    const { session } = options;
    const routes = {
        ...routesFor(session),
        ...addOnRoutes(options.addOns, (id) => ({
            connect: (entry, secrets) => {
                session.chooseBoard(id, entry, secrets);
            },
            installTool: (tool) => session.installTool(tool),
            changed,
        }), (id) => session.isOn(id)),
    };
    const server = createServer((incoming, response) => {
        void answer(incoming, response, { routes, watchers, ...options });
    });
    server.on("listening", () => {
        const address = server.address();
        const port = typeof address === "object" && address ? address.port : 0;
        options.session.serveToolsAt(`http://localhost:${String(port)}/api`);
        options.session.begin();
    });
    server.listen(options.port, "127.0.0.1");
    return { server, changed };
}
function routesFor(session) {
    const launcher = () => session.launcherOrRefuse();
    const part = (url) => decodeURIComponent(url.pathname.split("/")[3] ?? "");
    return {
        "GET /api/state": () => session.state(),
        "POST /api/setup/say": (body) => session.coach.say(text(body, "text"), optionalText(body, "spokenIn")),
        "POST /api/setup/draft": (body) => {
            session.ownerChangesDraft(body);
        },
        "POST /api/setup/build": () => session.build(),
        "POST /api/ideas": (body) => ({
            id: session.ideasOrRefuse().create(text(body, "text")),
        }),
        "POST /api/ideas/say": (body) => session
            .ideasOrRefuse()
            .say(text(body, "id"), text(body, "text"), optionalText(body, "spokenIn")),
        "POST /api/ideas/draft": (body) => {
            session
                .ideasOrRefuse()
                .ownerChange(text(body, "id"), body);
        },
        "POST /api/ideas/ready": (body) => {
            session.ideasOrRefuse().ready(text(body, "id"));
        },
        "POST /api/ideas/discard": (body) => {
            session.ideasOrRefuse().discard(text(body, "id"));
        },
        "POST /api/setup/open": () => {
            session.openFactory();
        },
        "POST /api/add-ons": (body) => {
            session.switchAddOn(text(body, "id"), body?.on === true);
        },
        "POST /api/connect/own-board": () => {
            session.chooseBoard("none");
        },
        "POST /api/settings": (body) => session.saveSettings(text(body, "group"), record(body, "values")),
        "POST /api/parts/start": (_b, url) => launcher().start(part(url)),
        "POST /api/parts/stop": (_b, url) => launcher().stop(part(url)),
        "POST /api/parts/restart": (_b, url) => launcher().restart(part(url)),
        "POST /api/start-all": () => launcher().startAll(),
        "POST /api/stop-all": () => launcher().stopAll(),
    };
}
async function answer(incoming, response, context) {
    const host = (incoming.headers.host ?? "").replace(/:\d+$/, "");
    const url = new URL(incoming.url ?? "/", "http://localhost");
    if (!HOSTS.has(host)) {
        send(response, 403, { error: "Not here." });
    }
    else if (url.pathname === "/api/events") {
        stream(response, context);
    }
    else if (url.pathname === COACH_TOOLS && incoming.method === "POST") {
        const body = await readBody(incoming).catch(() => null);
        await answerTools(incoming, response, context.session.coachTools(), body);
    }
    else if (IDEA_TOOLS.test(url.pathname) && incoming.method === "POST") {
        await ideaTools(incoming, response, context.session, url.pathname);
    }
    else if (url.pathname === PICTURE) {
        sendPicture(response, context.session, url.searchParams.get("path"));
    }
    else if (THEME_ROUTES.has(url.pathname)) {
        sendTheme(response, context.session.options.project, url);
    }
    else if (!url.pathname.startsWith("/api/")) {
        sendFile(response, context.page, url.pathname);
    }
    else {
        await answerApi(incoming, response, context.routes, url);
    }
}
async function answerApi(incoming, response, routes, url) {
    // /api/parts/<id>/start is the route "POST /api/parts/start".
    const path = url.pathname.replace(/^(\/api\/parts)\/[^/]+(\/\w+)$/, "$1$2");
    const route = routes[`${incoming.method ?? "GET"} ${path}`];
    if (!route) {
        send(response, 404, { error: "There is nothing here." });
        return;
    }
    if (incoming.method === "POST" && incoming.headers[PAGE_HEADER] !== "1") {
        send(response, 403, { error: "Only the factory's page may." });
        return;
    }
    try {
        const body = incoming.method === "POST" ? await readBody(incoming) : null;
        send(response, 200, (await route(body, url)) ?? {});
    }
    catch (error) {
        const refused = error instanceof Refused;
        const message = error instanceof Error ? error.message : String(error);
        send(response, refused ? 409 : 500, { error: message });
    }
}
function stream(response, context) {
    response.writeHead(200, {
        "content-type": "text/event-stream",
        "cache-control": "no-store",
        connection: "keep-alive",
    });
    context.watchers.add(response);
    response.on("close", () => context.watchers.delete(response));
    response.write(": connected\n\n");
}
function sendFile(response, page, path) {
    const wanted = normalize(join(page, decodeURIComponent(path)));
    const inside = wanted === page || wanted.startsWith(page + sep);
    const file = inside && existsSync(wanted) && statSync(wanted).isFile()
        ? wanted
        : join(page, "index.html");
    if (!existsSync(file)) {
        response.writeHead(503, { "content-type": "text/plain; charset=utf-8" });
        response.end("The web interface is not built yet: run npm run build in packages/dashboard.");
        return;
    }
    response.writeHead(200, {
        "content-type": TYPES[extname(file)] ?? "application/octet-stream",
    });
    response.end(readFileSync(file));
}
// One idea coach's tool call; an idea that is not there is said plainly.
async function ideaTools(incoming, response, session, path) {
    const id = IDEA_TOOLS.exec(path)?.[1] ?? "";
    const body = await readBody(incoming).catch(() => null);
    try {
        await answerTools(incoming, response, session.ideaTools(id), body);
    }
    catch (error) {
        if (!(error instanceof Refused))
            throw error;
        send(response, 404, { error: error.message });
    }
}
function sendPicture(response, session, path) {
    const file = path ? session.picture(path) : null;
    if (!file || !existsSync(file)) {
        send(response, 404, { error: "There is no such picture." });
        return;
    }
    response.writeHead(200, {
        "content-type": PICTURE_TYPES[extname(file).toLowerCase()] ?? "application/octet-stream",
        "cache-control": "no-store",
        "x-content-type-options": "nosniff",
    });
    response.end(readFileSync(file));
}
function send(response, status, body) {
    response.writeHead(status, {
        "content-type": "application/json",
        "cache-control": "no-store",
    });
    response.end(JSON.stringify(body));
}
async function readBody(incoming) {
    let text = "";
    for await (const chunk of incoming)
        text += String(chunk);
    if (!text)
        return {};
    try {
        return JSON.parse(text);
    }
    catch {
        throw new Refused("That request was not understood.");
    }
}
function text(body, key) {
    const value = body?.[key];
    if (typeof value !== "string")
        throw new Refused(`Say which ${key}.`);
    return value;
}
function optionalText(body, key) {
    const value = body?.[key];
    return typeof value === "string" ? value : undefined;
}
function record(body, key) {
    const value = body?.[key];
    if (typeof value !== "object" || value === null)
        throw new Refused(`Say the ${key}.`);
    return value;
}
